async function previewTeacherExam(exam,fromDrawer=false){try{let [links,pool]=await Promise.all([q('exam_questions','*',x=>x.eq('exam_id',exam.id).order('question_order')),q('exam_question_pool','*',x=>x.eq('exam_id',exam.id))]);let questions=links.map(l=>pool.find(p=>p.question_id===l.question_id)).filter(Boolean);if(!questions.length)return toast('Bài chưa có bộ câu mẫu',true);showTeacherPreviewQuestion(exam,questions,{},0,fromDrawer?'push':'open')}catch(ex){err(ex)}}
