async function submitStudentAttempt(payload,answers,auto){let unanswered=(payload.questions||[]).filter(q=>!answers[q.id]).length;if(!auto){let msg=unanswered?`Còn ${unanswered} câu chưa trả lời. Sau khi nộp bạn không thể sửa bài của lượt này.`:'Sau khi nộp bạn không thể sửa bài của lượt này. Xác nhận nộp bài?';if(!await confirmAction('Nộp bài kiểm tra',msg,{confirmLabel:'Nộp bài'}))return}clearTimer();let btn=$('#liveSubmit');if(btn){btn.disabled=true;btn.textContent=auto?'Hết giờ — đang nộp…':'Đang nộp…'}try{let {data,error}=await db.rpc('submit_exam_attempt',{p_attempt_id:payload.attempt_id,p_answers:answers||{}});if(error)throw error;showStudentResult(payload.exam,data)}catch(ex){err(ex);if(btn){btn.disabled=false;btn.textContent='Nộp bài'}}}
function showStudentResult(exam,result){clearTimer();replaceDrawer(`Kết quả · ${exam.title}`,resultHtml(exam,result),()=>{$('#studentAiAttempt')?.addEventListener('click',()=>requestAssessmentAi('attempt',result.attempt_id,null,$('#studentAiBox'),$('#studentAiAttempt')))},{wide:true,eyebrow:'KẾT QUẢ BÀI LÀM'})}
