function snapshotMap(data){let m=new Map();for(let aq of data.attemptQuestions)m.set(`${aq.attempt_id}|${aq.question_id}`,aq);return m}
function aggregateAnswers(data,answers,keyFn){let map=new Map(),meta=snapshotMap(data);for(let a of answers){let qx=meta.get(`${a.attempt_id}|${a.question_id}`);if(!qx)continue;let key=keyFn(qx);if(!key)continue;let x=map.get(key)||{correct:0,total:0};x.total++;if(a.is_correct)x.correct++;map.set(key,x)}return map}
