function studentMetrics(studentId,data){let attempts=data.submitted.filter(a=>a.student_id===studentId),ids=new Set(attempts.map(a=>a.id)),answers=data.answers.filter(a=>ids.has(a.attempt_id)),clo=aggregateAnswers(data,answers,qx=>qx.clo_code),chapter=aggregateAnswers(data,answers,qx=>qx.chapter_name),avg=attempts.reduce((s,a)=>s+num(a.score),0)/(attempts.length||1);return {attempts,answers,clo,chapter,avg}}
function attemptBreakdown(attemptId,data){let answers=data.answers.filter(a=>a.attempt_id===attemptId),clo=aggregateAnswers(data,answers,qx=>qx.clo_code);return [...clo.entries()].map(([code,x])=>({code,score:score10(x.correct,x.total),correct:x.correct,total:x.total}))}

